1	#!/usr/bin/env node
2	// PROTOTYPE gate runner for one component: `pnpm gate Button`.
3	// Runs gates 2 (+ static 7), 3, then 4/6/7 over the component's stories.
4	// Prints one summary; exit code 1 if any gate fails.
5	import { spawnSync } from "node:child_process";
6	import { readFileSync, existsSync, rmSync } from "node:fs";
7	
8	const component = process.argv[2];
9	if (!component) { console.error("usage: pnpm gate <Component>"); process.exit(2); }
10	const dir = `src/components/${component}`;
11	const run = (cmd, args, env = {}) => spawnSync(cmd, args, { encoding: "utf8", env: { ...process.env, ...env } });
12	const results = [];
13	rmSync("gates-out", { recursive: true, force: true });
14	
15	const lint = run("npx", ["eslint", dir]);
16	results.push({ gate: "2+7s token & taste lint (ESLint)", ok: lint.status === 0, detail: lint.stdout.trim() });
17	
18	const tsc = run("npx", ["tsc", "--noEmit", "--pretty", "false"]);
19	results.push({ gate: "3 typecheck", ok: tsc.status === 0, detail: tsc.stdout.trim() });
20	
21	const sb = run("npx", ["storybook", "build", "-o", "storybook-static", "--quiet"]);
22	if (sb.status !== 0) {
23	  results.push({ gate: "storybook build", ok: false, detail: (sb.stderr || sb.stdout).trim().split("\n").slice(-15).join("\n") });
24	} else {
25	  const pw = run("npx", ["playwright", "test", "--update-snapshots=missing"], { COMPONENT: component });
26	  let detail = "";
27	  if (existsSync("gates-out/playwright.json")) {
28	    const report = JSON.parse(readFileSync("gates-out/playwright.json", "utf8"));
29	    const lines = [];
30	    const walk = (s) => { for (const spec of s.specs ?? []) for (const t of spec.tests) for (const r of t.results) {
31	      if (r.status !== "passed") lines.push(`✗ ${spec.title}\n  ${(r.error?.message ?? "").replace(/\x1b\[[0-9;]*m/g, "").split("\n").map((l) => l.replace(/^Error: /, "")).filter((l) => l.startsWith("[gate") || /screenshot|baseline|pixels/i.test(l)).slice(0, 12).join("\n  ")}`);
32	      for (const a of r.attachments ?? []) if (a.name?.endsWith("-actual.png") && r.status !== "passed") lines.push(`  diff: ${a.path}`);
33	    } for (const c of s.suites ?? []) walk(c); };
34	    for (const s of report.suites) walk(s);
35	    detail = lines.join("\n");
36	  }
37	  results.push({ gate: "4/6/7r a11y, visual regression, render taste (Playwright)", ok: pw.status === 0, detail: detail || pw.stdout.trim().split("\n").slice(-20).join("\n") });
38	}
39	
40	for (const r of results) {
41	  console.log(`${r.ok ? "PASS" : "FAIL"}  ${r.gate}`);
